<main class="content container-fluid"><section class="card panel-card"><div class="card-body p-4 p-xl-5"><div class="d-flex flex-column flex-md-row align-items-md-center justify-content-between gap-3 mb-4"><div><span class="eyebrow"><?=$type==='test'?'EVALUACIÓN':'ANÁLISIS DE RESULTADOS'?></span><h2 class="mt-2 mb-1"><?=$type==='test'?'Tests':'Tabuladores'?></h2><p class="text-secondary mb-0"><?=$type==='test'?'Administra evaluaciones, archivos y enlaces por asignatura.':'Organiza los tabuladores por asignatura, grupo y subgrupo.'?></p></div><a class="btn btn-brand btn-lg" href="<?=url('/admin/recursos/formulario?type='.$type)?>">+ Nuevo <?=$type==='test'?'test':'tabulador'?></a></div><?php if(!$resources):?><div class="empty-state">Todavía no existen registros en este módulo.</div><?php else:?><div class="vstack gap-3"><?php foreach($resources as $r):?><article class="resource-row"><span class="resource-icon"><?=$type==='test'?'✓':'▦'?></span><div class="flex-grow-1"><span class="resource-meta"><?=e($r['subject']??'General')?><?=$r['group_name']?' · '.e($r['group_name']):''?></span><h3 class="h5 mb-1"><?=e($r['name'])?></h3><p class="text-secondary mb-0"><?=e($r['description']?:'Sin descripción')?></p></div><div class="d-flex flex-wrap gap-2"><a class="btn btn-sm btn-outline-success" href="<?=url('/admin/recursos/ver?id='.$r['id'])?>">Ver</a><a class="btn btn-sm btn-outline-primary" href="<?=url('/admin/recursos/formulario?id='.$r['id'])?>">Editar</a><form method="post" action="<?=url('/admin/recursos/eliminar')?>" onsubmit="return confirm('¿Eliminar este recurso?')"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="type" value="<?=$type?>"><button class="btn btn-sm btn-outline-danger">Eliminar</button></form></div></article><?php endforeach;?></div><?php endif;?></div></section></main>
